"use client";

import { PianoRoll as PianoRollPrimitive } from "@audio-ui/react";
import { cva, type VariantProps } from "class-variance-authority";
import { cn } from "@/lib/utils";

/** Mirrors the primitive's own default step count, used only to size the decorative grid lines when neither value nor defaultValue is passed. */
const DEFAULT_TOTAL_STEPS = 16;

const pianoRollVariants = cva("", {
  defaultVariants: {
    size: "default",
  },
  variants: {
    size: {
      default: "h-48",
      lg: "h-64",
      sm: "h-32",
    },
  },
});

interface PianoRollProps
  extends PianoRollPrimitive.RootProps,
    VariantProps<typeof pianoRollVariants> {
  /** Shows the playhead part. Position updates far too fast for React state — drive it via `playheadRef`. */
  isPlaying?: boolean;
  playheadRef?: React.RefObject<HTMLDivElement | null>;
}

export function PianoRoll({
  className,
  size,
  isPlaying,
  playheadRef,
  totalSteps = DEFAULT_TOTAL_STEPS,
  ...props
}: PianoRollProps) {
  return (
    <PianoRollPrimitive.Root
      className="flex w-full min-w-0 gap-2 data-[disabled=true]:cursor-not-allowed"
      totalSteps={totalSteps}
      {...props}
    >
      <PianoRollPrimitive.KeysTrack
        className={cn(
          "rounded-xl border border-transparent bg-card shadow-xs ring-1 ring-foreground/10 relative w-10 shrink-0 touch-none select-none overflow-hidden",
          pianoRollVariants({ size })
        )}
      >
        <PianoRollPrimitive.Keys>
          {(note) => (
            <PianoRollPrimitive.Key
              className="border-border/40 border-b bg-card transition-colors duration-150 ease-out last:border-b-0 motion-reduce:transition-none"
              key={note}
              note={note}
            />
          )}
        </PianoRollPrimitive.Keys>
      </PianoRollPrimitive.KeysTrack>
      <PianoRollPrimitive.Grid
        className={cn(
          "rounded-xl border border-transparent bg-card shadow-xs ring-1 ring-foreground/10 transition-[color,border-color,box-shadow,opacity] duration-150 ease-out hover:ring-4 hover:ring-ring/50 has-[:focus-visible]:ring-4 has-[:focus-visible]:ring-ring/50 active:ring-4 active:ring-ring/50 has-[:focus-visible]:border-ring active:border-ring motion-reduce:transition-none relative min-w-0 flex-1 touch-none select-none overflow-hidden",
          "focus-visible:outline-none",
          "data-[disabled=true]:pointer-events-none data-[disabled=true]:opacity-50",
          pianoRollVariants({ size }),
          className
        )}
        data-slot="piano-roll"
      >
        {Array.from({ length: totalSteps - 1 }, (_, i) => (
          <div
            className="pointer-events-none bg-border absolute inset-y-0 w-px"
            key={String(i)}
            style={{ left: `${((i + 1) / totalSteps) * 100}%` }}
          />
        ))}
        <PianoRollPrimitive.Notes>
          {(note) => (
            <PianoRollPrimitive.Note
              className="rounded-[min(var(--radius-sm),6px)] bg-primary transition-[background-color,box-shadow] duration-150 ease-out hover:ring-4 hover:ring-ring/50 focus-visible:ring-4 focus-visible:ring-ring/50 active:ring-4 active:ring-ring/50 data-[disabled=true]:pointer-events-none motion-reduce:transition-none cursor-grab touch-none select-none outline-none active:cursor-grabbing"
              id={note.id}
              key={note.id}
            >
              <PianoRollPrimitive.NoteHandle
                className="bg-foreground/20 transition-colors hover:bg-foreground/40 motion-reduce:transition-none inset-y-0 left-0 w-1.5 cursor-ew-resize"
                side="start"
              />
              <PianoRollPrimitive.NoteHandle
                className="bg-foreground/20 transition-colors hover:bg-foreground/40 motion-reduce:transition-none inset-y-0 right-0 w-1.5 cursor-ew-resize"
                side="end"
              />
            </PianoRollPrimitive.Note>
          )}
        </PianoRollPrimitive.Notes>
        {isPlaying ? (
          <PianoRollPrimitive.Playhead
            className="bg-foreground inset-y-0 w-px"
            ref={playheadRef}
          />
        ) : null}
      </PianoRollPrimitive.Grid>
    </PianoRollPrimitive.Root>
  );
}
